sketches.source:
setcpm(54/4)

// The hymn you were taught: four square chords on the organ, two bars each
// The organ steps through the interaural phase: 0 degrees sits in the centre of your head,
// 90 loosens, 180 spreads all around you and nearly vanishes in mono
hymn: note("<[c3,e3,g3,c4] [f2,c3,a3,c4] [g2,d3,b3,d4] [c3,e3,g3,c4]>").slow(2)
  .s("sawtooth").timbre("organ").iphase("<0 0 90 90 180 180 180 180>")
  .lpf(1400).attack(.6).sustain(.9).release(1.5).space("church").gain(.14)

// The pedal stays put, the same in both ears
pedal: note("<c2 f1 g1 c2>").slow(2).s("sawtooth").timbre("organ").lpf(450)
  .attack(.4).sustain(.8).release(1.5).space("church").gain(.2)

// From the fifth bar, a line of your own: lydian, unhurried, a few notes left out
// enter keeps it silent until bar 4; once it arrives, it stays
own: n("<[0 ~ 2 4] [6 ~ 4 ~] [7 ~ 6 4] [2@2 ~@2]>").scale("C:lydian").transpose(12)
  .degradeBy(.2).seed("own").enter(4)
  .s("triangle").timbre("soft").attack(.01).decay(1.2).sustain(.1).release(1.4)
  .room(.5).gain(.22)

setcpm(60/4)

// The chamber: the same few words, whispered from every side at once
const slogan = s("whisper*4").syl("<[sha ha sha ha] [ko ta ko ta]>").hpf(800)

// Each voice has its own place around your head, and each fades out in turn
// fadeout(k, at) lowers the gain over k bars, starting at bar at
left: slogan.azimuth(-90).distance(1.5).gain(.12).fadeout(4, 4)
right: slogan.late(1/8).azimuth(90).distance(1.5).gain(.12).fadeout(4, 6)
behind: slogan.late(1/4).azimuth(180).distance(2).gain(.1).fadeout(4, 8)
above: slogan.late(3/8).elevation(60).distance(2).gain(.1).fadeout(4, 10)

// What is left when they have gone: a still pad in the middle, and your breath
pad: note("<[d3,a3,e4] [b2,f#3,d4]>").slow(4).s("sawtooth").unison(3).detune(.2)
  .lpf(1100).attack(3).sustain(1).release(4).room(.6).gain(.12).fadein(12)
breath: s("pink").slow(2).hpf(300).lpf(900).attack(3).release(4).gain(.04).fadein(12)

setcpm(50/4)

// One certainty in unison, then the ears drift apart in cents, two bars at a time, and back
// earsh raises the right ear and lowers the left by half the value each
// 0 cents is one point; 3 beats slowly; 8 and 15 shimmer; 30 opens into two views at once
drone: note("[d2,a2,d3]").s("sawtooth").earsh("<0 0 3 3 8 8 15 15 30 30 15 15 8 8 3 3>")
  .lpf(900).attack(1.5).sustain(1).release(1.5).gain(.16)

// A piano in the middle of your head, asking and answering: D, Bm, G, A
piano: note("<[f#4@3 e4] [d4@4] [d4@2 f#4 b4] [a4@4] [b4@3 a4] [g4@2 d4@2] [e4@2 f#4 a4] [a4@4]>")
  .s("triangle").timbre("soft").attack(.005).decay(1.4).sustain(.1).release(1.6)
  .room(.6).gain(.24)

// Low chords holding the key
chords: note("<[d3,f#3,a3] [b2,d3,f#3] [g2,b2,d3] [a2,c#3,e3]>").slow(2)
  .s("triangle").timbre("soft").attack(1).sustain(.6).release(2).lpf(1000).room(.6).gain(.14)

setcpm(56/4)

// irate turns the phase between the ears, in turns per second: an idea rolled over slowly
// All rates stay below 3 Hz, so no pulse warning is needed
drone: note("[e2,b2]").s("sine").irate("<.2 .2 .4 .4 .8 .8 .4 .4>")
  .attack(1).sustain(1).release(1).gain(.24)

// Four bars of questions in the whole-tone scale, which has no home note,
// then four bars of an answer in lydian that is allowed to stay open
const question = n("<[0 1 2 3] [4@3 3] [2 3 4 5] [6@4]>").scale("E:whole tone").transpose(12)
const answer = n("<[0 1 2 4] [5@3 4] [3 2 1 2] [4@4]>").scale("E:lydian").transpose(12)
melody: form("A@4 B@4", question, answer)
  .s("sine").timbre("hollow").vib(4.5).vibdepth(.12)
  .attack(.08).sustain(.6).release(.8).room(.6).gain(.22)

// A pad that follows the same form: an augmented chord for the questions, open chords for the answer
pad: form("A@4 B@4", note("[e3,g#3,c4]"), note("<[e3,g#3,b3] [a2,c#3,e3,g#3]>").slow(2))
  .s("sawtooth").unison(3).detune(.2).lpf(1200)
  .attack(1.5).sustain(.9).release(2).room(.6).gain(.1)

setcpm(60/4)

// A quiet spring nearby and a breeze
spring: s("stream").slow(4).azimuth(-40).distance(3).gain(.16)
breeze: s("wind").slow(8).intensity(.15).gain(.06)

// The same noise feeds both ears, but one ear's noise is phase-shifted in a narrow band
// Neither ear alone hears a tone; only the two together hear the tune between them
tune: s("white*4").dichotic("<[294 370 440 587] [494 440 370 330] [370 440 494 659] [554 440 330 440]>")
  .dichoticq(30).attack(.02).sustain(1).release(.05).gain(.14)

// A quiet hint: the first phrase on a sine, once every four bars
hint: note("<[d4 f#4 a4 d5] ~ ~ ~>").s("sine")
  .decay(.3).sustain(.3).release(.2).gain(.08)

// A soft pad holding the key: D, Bm, G, A
pad: note("<[d3,a3,f#4] [b2,f#3,d4] [g2,d3,b3] [a2,e3,c#4]>")
  .s("triangle").timbre("soft").attack(1).sustain(.6).release(2)
  .lpf(1000).room(.6).gain(.12)

setcpm(40/4)

// icorr 1: the same noise in both ears, a narrow point in the middle of your head
// icorr near 0: unrelated noise in each ear, wide and all around you
air: s("pink").icorr("<1 .8 .6 .4 .2 .1 .1 .1>").lpf(2500)
  .attack(.5).sustain(1).release(.5).gain(.1)

// A 2 Hz binaural drone: each ear is detuned by 1 Hz, below the 3-30 Hz warning range
drone: note("<g1 g1 eb1 f1>").slow(2).s("sine").binaural(2)
  .attack(4).sustain(1).release(6).gain(.26)

// A pad that barely moves, and a bell at each step outward
pad: note("<[g2,d3,bb3] [eb2,bb2,g3]>").slow(4).s("sawtooth").unison(4).detune(.3)
  .attack(4).release(6).lpf(700).room(.8).size(.9).gain(.1)
bell: note("d5").s("sine").fm(2).fmh(2.76)
  .decay(4).sustain(0).release(4).space("hall").gain(.08)

setcpm(44/4)

// A 6 Hz binaural beat in the theta range: each ear is detuned by 3 Hz. Keep the volume low
drone: note("<a1 a1 f1 g1>").slow(4).s("sine").binaural(6)
  .attack(4).sustain(1).release(6).gain(.22)

// Slow, breathing choir chords: Am, F, C, G
choir: note("<[a2,e3,c4] [f2,c3,a3] [c3,g3,e4] [g2,d3,b3]>").slow(2)
  .s("choir").syl("<oo ah oh ah>").attack(3).release(4).space("hall").gain(.2)

// Pieces coming back together: earsplit("harmonics") alternates the partials between the ears
// Each ear hears a thinner chord; only both together, or mono, hear it whole
pad: note("<[a3,c4,e4] [f3,a3,c4] [c4,e4,g4] [g3,b3,d4]>").slow(2)
  .s("sawtooth").earsplit("harmonics").lpf(1400)
  .attack(2).sustain(1).release(3).room(.6).gain(.1)

// A stream nearby
stream: s("stream").slow(4).azimuth(60).distance(4).gain(.14)
